function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function get(path) {
  const response = await fetch(apiOrigin() + path, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}

async function run(input) {
  const backtestLimit = Math.max(1, Math.min(20, Number(input.backtest_limit || 5)))
  const symbolLimit = Math.max(1, Math.min(100, Number(input.symbol_limit || 30)))
  const [providers, symbolCatalog, strategies, backtests] = await Promise.all([
    get('/api/data/providers'),
    get('/api/data/market/symbols'),
    get('/api/strategies'),
    get('/api/backtests?limit=' + backtestLimit),
  ])
  const allSymbols = Array.isArray(symbolCatalog.symbols) ? symbolCatalog.symbols : []
  return { providers, symbols: allSymbols.slice(0, symbolLimit), symbolCount: allSymbols.length, strategies, backtests, observedAt: new Date().toISOString() }
}

