function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const response = await fetch(apiOrigin() + '/api/backtests/run', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify({
      strategy_id: String(input.strategy_id || '').trim(),
      start_date: String(input.start_date || '').trim(),
      end_date: String(input.end_date || '').trim(),
    }),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}

